/* Corps v3 en kraft : ~70 plans courts, chacun calé sur un mot de la voix : at = [phrase, mot] */
const V = [], v = (at, o) => V.push(Object.assign(o, { at }));
const AT = (s, w) => ALLWORDS[s][w].start, loc = (self, s, w) => AT(s, w) - self._start;
const pp = K.pop, Cc = K.C, CX = 540;
const TONE = ["#F3D9C2", "#E8BE9B", "#CF9A72", "#A9704B", "#7C4A30", "#4B2B1E"];
const pool = (p, n, r) => Array.from({ length: n }, (_, i) => K.spot(p, 0, 0, r, i + 1));
const rise = (ds, t, cx, y0, y1, spread, speed, amt = 1) => ds.forEach((q, i) => { const ph = (t * speed + i / ds.length) % 1, on = i / ds.length < amt; H.set(q, { x: cx + Math.sin(i * 2.3 + t * 2) * spread, y: lerp(y0, y1, E.out(ph)), s: on ? (.4 + .6 * Math.min(1, ph * 3)) : 0, o: on && ph < .96 ? 1 : 0 }); });
const sweep = (g, t, p, a, b, cx, cy, rx, ry, n = 4) => { const r = seg(p, a, b); H.set(g, { x: cx + Math.sin(r * Math.PI * 2 * n) * rx, y: cy + Math.cos(r * Math.PI * n) * ry, r: Math.sin(r * Math.PI * 2 * n) * 10, o: r > 0 && r < 1 ? 1 : 0 }); };
const title = (L, txt, y = 330, o = {}) => K.label(L, txt, CX, y, Object.assign({ size: 64, maxw: 740 }, o));
const numTitle = (self, L, n, txt, col) => { self.bd = K.badge(L, n, 190, 290, col); self.tt = K.label(L, txt, 640, 290, { size: 56, maxw: 560, pad: [34, 18] }); };
const numIn = (self, p) => { pp(self.bd, p, .02, .2); H.set(self.tt, { x: lerp(1300, 630, E.out(seg(p, .05, .3))), o: p > .05 ? 1 : 0 }); };
const trig = (at, id, tone, lab, mk, sfx) => v(at, { id, sfx,
  init(L) { K.panel(L.bg, tone); this.tt = title(L.mid, lab); this.ob = mk(L.mid); this.ce = K.cell(L.mid, 760, 900, 1.5); this.ar = K.arrow(L.mid, 480, 790, 640, 850, Cc.red, 40); this.bu = K.burst(L.mid, 90, 130, 12, Cc.red); H.set(this.ob, { x: 290, y: 760 }); },
  update(t, p, d, L) { H.look(L, 0, 0, lerp(1, 1.06, p)); pp(this.tt, p, .02, .18); pp(this.ob, p, .05, .25); H.set(this.ar, { sx: E.out(seg(p, .3, .5)), o: p > .3 ? 1 : 0 }); const k = seg(p, .5, .7); H.set(this.bu, { x: 760, y: 870, s: E.pop(k) * (1 + .1 * Math.sin(t * 14)), o: k > 0 ? .95 : 0, r: t * 40 }); H.set(this.ce.q, { s: 1 + .08 * Math.sin(t * 18) * seg(p, .5, 1) }); } });

